/* Presentation layer for the audited Task-3 analogue export. */
document.addEventListener('DOMContentLoaded', () => {
  const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
  const parseCSV = (text) => {
    const lines = text.trim().split(/\r?\n/).filter(Boolean);
    if (!lines.length) return [];
    const split = (line) => line.match(/("(?:[^"]|"")*"|[^,]+)/g)?.map((cell) => cell.replace(/^"|"$/g, '').replace(/""/g, '"').trim()) || [];
    const header = split(lines[0]);
    return lines.slice(1).map((line) => {
      const cells = split(line);
      const row = {};
      header.forEach((key, i) => { row[key] = cells[i] ?? ''; });
      return row;
    });
  };
  const compactSummaryTable = async () => {
    const url = `${newRoot}task3b_robustness/task3_vs_paper_summary_statistics.csv`;
    try {
      const response = await fetch(url, {cache: 'no-store'});
      if (!response.ok) return `<p>Summary table unavailable (${response.status}). Download CSV instead.</p>`;
      const rows = parseCSV(await response.text()).filter((row) => ['mean_individual', 'count_pooled', 'equal_pooled'].includes(row.pupil_summary));
      const cols = [
        ['embedding', 'Embedding'],
        ['scale', 'Scale'],
        ['pupil_summary', 'Pupil summary'],
        ['n_families', 'Families'],
        ['slope', 'Slope'],
        ['r2', 'R²'],
        ['d_mean', 'Mean pupil–tutor change'],
        ['d_diff', 'Below-minus-above tutor change'],
      ];
      return `<div class="table-wrap" tabindex="0"><table><caption>Task-3 and paper benchmark statistics (all-available families)</caption><thead><tr>${cols.map(([, label]) => `<th scope="col">${esc(label)}</th>`).join('')}</tr></thead><tbody>${rows.map((row) => `<tr>${cols.map(([key]) => `<td>${esc(row[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p><a download href="${url}">Download full benchmark CSV</a></p>`;
    } catch (error) {
      return `<p>Summary table unavailable (${esc(error.message)}). Download CSV instead.</p>`;
    }
  };
  const oldRoot = 'balanced-imitation-20261019/';
  const newRoot = 'balanced-imitation-20261027b/';
  const section = document.querySelector('#bi-analogue');
  if (!section || section.dataset.task3Audit20261023) return;
  section.dataset.task3Audit20261023 = 'true';
  section.querySelectorAll('img[src^="' + oldRoot + '"], a[href^="' + oldRoot + '"]').forEach(node => {
    const attribute = node.tagName === 'IMG' ? 'src' : 'href';
    node.setAttribute(attribute, node.getAttribute(attribute).replace(oldRoot, newRoot));
  });
  const figure = section.querySelector('img[src$="fig_analogue_4h_family_lines.png"]');
  if (figure) {
    figure.width = 2470; figure.height = 2210;
    figure.alt = 'Four by four family-line entropy analogue: raw and normalized mean individual and raw-count-pooled pupil entropy across four embeddings';
    const caption = figure.closest('figure')?.querySelector('figcaption');
    if (caption) caption.firstChild.textContent = 'Audited 4×4 family-line analogue. Pooled-panel annotations now use the pooled endpoints shown. ';
  }
  const ceiling = document.createElement('figure');
  ceiling.innerHTML = `<img loading="lazy" width="1560" height="585" src="${newRoot}task3_analogue/fig_family_cluster_ceiling_distribution.png" alt="Distributions of family-specific category counts and entropy ceilings"><figcaption>Distribution of K_family and log2(K_family); noise category −1 is included. <a download href="${newRoot}task3_analogue/fig_family_cluster_ceiling_distribution.png">Download</a></figcaption>`;
  figure?.closest('figure')?.after(ceiling);
  const auditLinks = document.createElement('p');
  auditLinks.innerHTML = `<a download href="${newRoot}task3_analogue/task3_data_audit.md">Data audit report</a> · <a download href="${newRoot}task3_analogue/task3_record_provenance.csv">record provenance</a> · <a download href="${newRoot}task3_analogue/task3_family_membership_audit.csv">family membership audit</a> · <a download href="${newRoot}task3_analogue/task3_cluster_cardinality_audit.csv">cluster-cardinality audit</a> · <a download href="${newRoot}task3_analogue/illustrative_panel_statistics.csv">displayed panel statistics</a> · <a download href="${newRoot}task3_analogue/illustrative_family_cluster_ceilings.csv">named K_family table</a>`;
  ceiling.after(auditLinks);
  const explanation = document.createElement('section');
  explanation.className = 'how-to-read';
  explanation.innerHTML = `<h3>What the family-entropy lines measure</h3><p>For a distribution p over K shared within-family categories, Shannon entropy is <code>H(p) = −Σ pₖ log₂ pₖ</code>, with <code>0 log₂ 0 = 0</code>. Each family has its own partition, so the normalized display is <code>H_norm,j = Hⱼ / log₂(Kⱼ)</code>. This accounts for different theoretical ceilings, but does not make distinct embedding geometries biologically equivalent.</p><p><strong>Mean individual pupil entropy</strong> is <code>mean H(P) = (1/n)ΣH(Pᵢ)</code>; each pupil has equal weight. Its tutor contrast is <code>mean ΔH = mean H(P) − H(T)</code>. <strong>Raw pooled pupil entropy</strong> instead uses <code>p_count = Σwᵢpᵢ</code>, where <code>wᵢ = Nᵢ/ΣNᵢ</code>: pupils with more observations receive more weight. The displayed pooled contrast is <code>H(p_count) − H(T)</code>.</p><p>An equal-weight pooled alternative is <code>p_equal = (1/n)Σpᵢ</code>, with entropy <code>H(p_equal)</code>. It is documented here but not added to this Task-3 figure. Correct pooling gains require matched weights: <code>H(p_equal) − mean H(P) ≥ 0</code> and <code>H(p_count) − ΣwᵢH(Pᵢ) ≥ 0</code>. The difference <code>H(p_count) − mean H(P)</code> is not, by itself, a Jensen gap.</p><h3>Individual diversity versus collective diversity</h3><p>Individual and pooled pupil entropy answer different scientific questions. Mean individual entropy asks whether a typical pupil has a more diverse vocal-state distribution than its tutor. Pooled entropy asks how diverse the pupils’ combined repertoire is. A family can have <code>mean H(P) &lt; H(T)</code> while <code>H(p_count) &gt; H(T)</code>, consistent with complementary pupil repertoires. Entropy alone cannot establish which tutor states were reproduced, better imitation, or a causal learning effect.</p><p>The dashed line is the median of included family tutors on the displayed scale. The historical <code>rev_share</code> statistic instead uses separate tutor and pupil-summary medians; it is a relative-median-crossing metric, not crossing one common entropy threshold.</p>`;
  auditLinks.after(explanation);
  const interpretation = document.createElement('section');
  interpretation.className = 'how-to-read';
  interpretation.innerHTML = `<h3>Embedding-dependent representations and normalization</h3><p>These tutor–pupil relationships depend on the family-shared embedding and clustering geometry. In these descriptive analyses, PCoA, UMAP, and PHATE show one broad pattern, whereas LR=200 t-SNE shows a noticeably different tutor-entropy/tutor-to-pupil relationship across families. This indicates sensitivity of entropy summaries to embedding geometry; it does not identify one embedding as biologically correct. Read the figure as a comparison of embedding-dependent representations, rather than as one embedding-independent truth.</p><p>Within one family, tutor and pupils share the same ceiling, so <code>sign((H(P) − H(T)) / log₂K) = sign(H(P) − H(T))</code>: normalization preserves the within-family direction of change. Families have different <code>K_family</code>, however, so dividing each family by <code>log₂(K_family)</code> can change across-family slopes and R². This is a methodological clarification, not a flaw.</p><h3>Why does t-SNE look different?</h3><p>For families matched across all four illustrative embeddings, t-SNE tutor entropies and tutor-to-pupil changes agree only weakly with the other representations, while UMAP and PHATE agree more strongly with each other. The accompanying matched-family Spearman displays make this explicit. This is a distinct embedding-dependent view of the same families, not a verdict that t-SNE is invalid.</p><h3>Paper reference and definitions</h3><p>The paper reference uses a fixed 10-cluster vocal-state partition: <code>H_norm = H / log₂(10)</code>. Task 3 instead uses family-specific shared partitions: <code>H_norm,j = H_j / log₂(K_j)</code>. They are displayed together only as a labelled descriptive benchmark, not as interchangeable pipelines. Definitions: <code>H(p) = −Σpₖlog₂pₖ</code>; <code>mean H(P) = (1/n)ΣH(Pᵢ)</code>; and count pooling uses <code>p_count = Σwᵢpᵢ</code>, <code>wᵢ = Nᵢ/ΣNᵢ</code>, then <code>H_count = H(p_count)</code>.</p>`;
  explanation.after(interpretation);
  const comparison = document.createElement('section');
  comparison.className = 'how-to-read';
  comparison.innerHTML = `<h3>Matched-family embedding comparison and paper benchmark</h3><p>UMAP and PHATE exhibit strong agreement in the ranks of tutor entropies and pupil–tutor changes for the matched families, while t-SNE shows weaker agreement with the other representations. The t-SNE results also originate from a distinct LR=200 sensitivity run, so these comparisons should not be interpreted as isolating the embedding algorithm as the sole cause of the difference.</p><p>All-available-family regression comparisons and matched-family regression comparisons answer slightly different questions. Comparing identical family sets reduces sample-composition differences, but does not make the embedding geometries equivalent.</p><figure><img loading="lazy" width="1820" height="560" src="${newRoot}task3b_robustness/fig_embedding_agreement_raw.png" alt="Matched-family Spearman agreement heatmaps for raw tutor entropy and tutor-to-pupil changes"><figcaption>Matched-family Spearman agreement, raw entropy scale. Shared color range is −1 to +1. <a download href="${newRoot}task3b_robustness/fig_embedding_agreement_raw.png">Download</a></figcaption></figure><figure><img loading="lazy" width="1820" height="560" src="${newRoot}task3b_robustness/fig_embedding_agreement_normalized.png" alt="Matched-family Spearman agreement heatmaps for normalized tutor entropy and tutor-to-pupil changes"><figcaption>Matched-family Spearman agreement, normalized entropy scale. Shared color range is −1 to +1. <a download href="${newRoot}task3b_robustness/fig_embedding_agreement_normalized.png">Download</a></figcaption></figure><figure><img loading="lazy" width="1820" height="1040" src="${newRoot}task3b_robustness/fig_task3_vs_paper_summary.png" alt="Raw and normalized family-level slopes for all-available Task 3 embeddings and the fixed-ten-cluster paper reference"><figcaption>All-available-family benchmark (Task-3 embeddings retain their own available families; paper remains a separate fixed-10 reference). <a download href="${newRoot}task3b_robustness/fig_task3_vs_paper_summary.png">Download</a></figcaption></figure><figure><img loading="lazy" width="1950" height="1040" src="${newRoot}task3b_robustness/fig_task3_vs_paper_matched43_summary.png" alt="Raw and normalized family-level slopes for matched 43 Task 3 families plus separate paper reference"><figcaption>Matched-43 benchmark for Task 3 embeddings; paper stays separate and unmatched. <a download href="${newRoot}task3b_robustness/fig_task3_vs_paper_matched43_summary.png">Download</a></figcaption></figure><div id="task3b-benchmark-table"><p>Loading compact benchmark table…</p></div><p><a download href="${newRoot}task3b_robustness/cross_embedding_agreement_three_pooling.csv">matched-family agreement table (mean/count/equal pooled)</a> · <a download href="${newRoot}task3b_robustness/spearman_agreement_matrices.csv">Spearman matrix values</a> · <a download href="${newRoot}task3b_robustness/task3_vs_paper_summary_statistics.csv">Task-3 and paper summary statistics</a> · <a download href="${newRoot}task3b_robustness/task3_vs_paper_matched43_summary_statistics.csv">matched-43 Task-3 summary statistics</a> · <a download href="${newRoot}task3b_robustness/matched_families_comparison.csv">existing matched-family robustness table</a></p>`;
  const paperRoot = `${newRoot}task3b_paper_reference_final_v3/`;
  const paperAgreement = document.createElement('section');
  paperAgreement.className = 'how-to-read';
  paperAgreement.innerHTML = `<h3>Comparing family entropy rankings with the paper reference</h3><p>The matrices above compare four Task-3 embedding-based representations. The additional matrices below add the paper-derived fixed-ten-state vocal partition as an external methodological reference, not as a fifth embedding. This asks whether the methods rank the same tutor families similarly; it does not make their acoustic partitions equivalent.</p><p>The four-method Task-3 intersection contains 43 families, and all 43 have a verified paper-tutor identity through the published numeric tutor ID → source Colony Info Index/Band Number → exact normalized full local band ID chain. The paper reproduction contains 68 tutor families: 43 are verified for this analysis, 25 are unmatched to the common four-method population, and none are ambiguous. Published pupil rosters match Task-3 membership for all 43. Recording-interval equivalence is not established: the paper exports 10-ms vocal-state windows while Task 3 exports segmented-syllable category counts, and the available exports do not retain comparable per-recording interval IDs.</p><p>Spearman requires paired values for the same verified tutor families. Here <code>aⱼ</code> and <code>bⱼ</code> are endpoint values from methods A and B for biological tutor <code>j</code>, one observation per family, with the same <code>N=43</code> identities in every cell. The common population is <code>F_common = F_PCoA ∩ F_UMAP ∩ F_PHATE ∩ F_tSNE ∩ F_paper</code>. Each vector is converted to ranks; ties receive average ranks, as in <code>scipy.stats.spearmanr</code>.</p><p><code>ρ_s = Corr(rank(a), rank(b))</code></p><p>Equivalently, using ranks <code>Rⱼ</code> and <code>Sⱼ</code> with means <code>R̄</code> and <code>S̄</code>:</p><p><code>ρ_s = Σⱼ(Rⱼ−R̄)(Sⱼ−S̄) / √[Σⱼ(Rⱼ−R̄)² · Σⱼ(Sⱼ−S̄)²]</code></p><p>Only when there are no ties may the shortcut <code>ρ_s = 1 − 6Σⱼdⱼ²/[N(N²−1)]</code> be used, where <code>dⱼ=Rⱼ−Sⱼ</code>.</p><p><strong>Interpretation.</strong> <code>+1</code> means identical family rank order, <code>−1</code> means exactly reversed order, and values near zero indicate little monotonic rank association. Positive correlation does not mean equal entropy magnitudes. For tutor entropy it describes agreement about which tutors rank relatively high or low in diversity. For pupil–tutor changes it describes relative change rankings, not whether each change has the same positive or negative sign. These correlations are not an imitation score or evidence that one representation is biologically correct.</p><p><strong>Raw and normalized scales.</strong> Paper entropy uses <code>H_norm = H/log₂(10)</code>, a constant denominator that preserves paper-family ranks. Task 3 uses <code>H_norm,j = Hⱼ/log₂(Kⱼ)</code>, with a family-specific category count, so cross-family rank order can change and raw and normalized correlations can differ. This differs from within-family sign preservation: tutor and pupils share the same <code>Kⱼ</code>, so <code>sign(ΔH_norm,j)=sign(ΔH_raw,j)</code>.</p><p>The endpoints are tutor entropy <code>X=H(T)</code>, mean-individual change <code>Δ_mean=(1/n)ΣᵢH(Pᵢ)−X</code>, count-pooled change <code>Δ_count=H(Σᵢwᵢpᵢ)−X</code> with <code>wᵢ=Nᵢ/ΣₗNₗ</code>, and equal-pooled change <code>Δ_equal=H((1/n)Σᵢpᵢ)−X</code>. Task-3 values use its family-shared partition; paper values use the Task-1 fixed-ten-state reproduction.</p><figure><img loading="lazy" decoding="async" width="3840" height="1152" src="${paperRoot}fig_embedding_agreement_with_paper_raw.png" alt="Five-method raw Spearman matrices comparing four Task-3 embeddings and the paper fixed-ten-state reference across 43 verified tutor families"><figcaption>Five-method Spearman agreement, raw entropy; 43 verified matched tutor families. Paper-reference cells are outlined. <a download href="${paperRoot}fig_embedding_agreement_with_paper_raw.png">Download</a></figcaption></figure><figure><img loading="lazy" decoding="async" width="3840" height="1152" src="${paperRoot}fig_embedding_agreement_with_paper_normalized.png" alt="Five-method normalized Spearman matrices comparing four Task-3 embeddings and the paper fixed-ten-state reference across 43 verified tutor families"><figcaption>Five-method Spearman agreement, normalized entropy; 43 verified matched tutor families. Paper-reference cells are outlined. <a download href="${paperRoot}fig_embedding_agreement_with_paper_normalized.png">Download</a></figcaption></figure><p><a download href="${paperRoot}cross_method_agreement_with_paper_raw.csv">Raw five-method correlations</a> · <a download href="${paperRoot}cross_method_agreement_with_paper_normalized.csv">Normalized five-method correlations</a> · <a download href="${paperRoot}paper_task3_verified_family_mapping.csv">Verified family mapping</a> · <a download href="${paperRoot}paper_task3_matched_family_values.csv">Matched family values</a> · <a download href="${paperRoot}paper_task3_family_membership_audit.csv">Pupil membership audit</a> · <a download href="${paperRoot}mapping_audit.md">Mapping and limitations report</a> · <a download href="${paperRoot}mapping_audit.json">Validation summary</a></p>`;
  paperAgreement.innerHTML = paperAgreement.innerHTML
    .replace('43 are verified for this analysis, 25 are unmatched to the common four-method population, and none are ambiguous.', 'the published-to-local crosswalk verifies 61 of 68 tutor identities; 43 are eligible for this analysis, 7 remain unresolved, and 18 verified identities are outside the four-method common set.')
    .replace('<strong>Interpretation.</strong> <code>+1</code>', '<strong>Interpretation.</strong> <code>−1 ≤ ρ_s ≤ +1</code>; <code>+1</code>');
  const normalizedAgreement = comparison.querySelector('img[src$="fig_embedding_agreement_normalized.png"]');
  normalizedAgreement?.closest('figure')?.after(paperAgreement);
  interpretation.after(comparison);
  compactSummaryTable().then((html) => {
    const mount = comparison.querySelector('#task3b-benchmark-table');
    if (mount) mount.innerHTML = html;
  });
});
